svg.script:
(function(){
var SVG='http://www.w3.org/2000/svg';
var root=document.getElementById('liftRoot'); if(!root) return;
function ns(t,a,txt){var e=document.createElementNS(SVG,t);if(a)for(var k in a)e.setAttribute(k,a[k]);if(txt!=null)e.textContent=txt;root.appendChild(e);return e;}

// --- geometry (sunrise worked example: 70.2 deg sweep, 4:1 gear -> 17.55 deg) ---
var L_mm=80, thetaMaxDeg=17.55, scale=3.7;
var L_px=L_mm*scale;              // 296 px = 80 mm
var Px=408, Py=250;               // pivot (fixed, right-hand end)
var Gx=Px-L_px, Gy=Py;            // grounded free-end (left)
var thetaMax=thetaMaxDeg*Math.PI/180;

// static reference guides
ns('line',{x1:Gx-26,y1:Py,x2:Px+18,y2:Py,'class':'ground'});   // ground
ns('line',{x1:Gx,y1:Py+6,x2:Gx,y2:Py-112,'class':'ground'});   // vertical at left

// static base (the arm's grounded position, = L)
ns('line',{x1:Gx,y1:Gy,x2:Px,y2:Py,'class':'base','stroke-width':2});
ns('text',{x:(Gx+Px)/2,y:Py+22,'font-size':14,'class':'lab','text-anchor':'middle'},'L = 80 mm');

// right-angle marker at the free end
ns('path',{d:'M'+(Gx+13)+' '+Gy+' L'+(Gx+13)+' '+(Gy-13)+' L'+Gx+' '+(Gy-13),'class':'rt','stroke-width':1.4});

// pivot (hinge)
ns('circle',{cx:Px,cy:Py,r:7,'class':'hinge'});
ns('circle',{cx:Px,cy:Py,r:3,'class':'dot'});

// title + live readout (top-left, always clear of the triangle)
var roTheta=ns('text',{x:Gx-26,y:66,'font-size':15,'class':'read'},'');
var roT=ns('text',{x:Gx-26,y:90,'font-size':15,'class':'read'},'');

// moving parts
var leg=ns('line',{x1:Gx,y1:Gy,x2:Gx,y2:Gy,'class':'throw','stroke-width':3});
var arm=ns('line',{x1:Px,y1:Py,x2:Gx,y2:Gy,'class':'arm','stroke-width':3});
var arc=ns('polyline',{points:'','class':'arc','stroke-width':2.2});
var endDot=ns('circle',{cx:Gx,cy:Gy,r:4.5,'class':'dot'});
var tLet=ns('text',{x:Gx-10,y:Gy,'font-size':15,'class':'tlet','text-anchor':'end'},'t');
var thLet=ns('text',{x:Px-60,y:Py-6,'font-size':15,'class':'thlet','text-anchor':'end'},'\u03B8');

function setTheta(th){
  var tpx=L_px*Math.tan(th);
  var Fx=Gx, Fy=Py-tpx;
  arm.setAttribute('x2',Fx); arm.setAttribute('y2',Fy.toFixed(2));
  leg.setAttribute('x2',Fx); leg.setAttribute('y2',Fy.toFixed(2));
  endDot.setAttribute('cx',Fx); endDot.setAttribute('cy',Fy.toFixed(2));
  var R=52,pts='',k,steps=10;
  for(k=0;k<=steps;k++){var a=th*k/steps; pts+=(Px-R*Math.cos(a)).toFixed(1)+','+(Py-R*Math.sin(a)).toFixed(1)+' ';}
  arc.setAttribute('points',pts.trim());
  tLet.setAttribute('y',((Py+Fy)/2+4).toFixed(1));
  var ab=th/2,Rl=66;
  thLet.setAttribute('x',(Px-Rl*Math.cos(ab)).toFixed(1));
  thLet.setAttribute('y',(Py-Rl*Math.sin(ab)+4).toFixed(1));
  roTheta.textContent='\u03B8 = '+(th*180/Math.PI).toFixed(1)+'\u00B0';
  roT.textContent='t = '+(80*Math.tan(th)).toFixed(1)+' mm';
}

var reduce=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
if(reduce){ setTheta(thetaMax); return; }

var Tr=3000,Tt=2000,Tf=3000,Tb=1000,cyc=Tr+Tt+Tf+Tb,t0=null;
function smooth(u){return u*u*(3-2*u);}
function frame(ts){
  if(t0==null)t0=ts;
  var e=(ts-t0)%cyc,u;
  if(e<Tr) u=smooth(e/Tr);
  else if(e<Tr+Tt) u=1;
  else if(e<Tr+Tt+Tf) u=smooth(1-(e-Tr-Tt)/Tf);
  else u=0;
  setTheta(u*thetaMax);
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);
})();
